// PagerRTTY line -> CoT. Input msg.payload: "<rxhost>|DE CALL TYPE [POS lat lon] [TXT text] HHMMZ CKxx"
const STALE_MIN = 30;      // position marker stale (minutes) - set just past your beacon interval
const DEDUP_SEC = 120;     // repeats of the same message inside this window are dropped

let raw = String(msg.payload).trim();
let rx = "rx";
const bar = raw.indexOf("|");
if (bar >= 0) { rx = raw.slice(0, bar); raw = raw.slice(bar + 1).trim(); }

const m = raw.match(/DE (\S+) (LOC|SALUTE|SITREP|MSG|TEST)( POS (\d{2}\.\d{4})([NS]) (\d{3}\.\d{4})([EW]))?( TXT (.*?))? (\d{4})Z CK([0-9A-F]{2})\s*$/);
if (!m) { node.status({fill:"grey", shape:"ring", text:"no frame: " + raw.slice(0, 30)}); return null; }

const body = raw.slice(raw.indexOf("DE "), raw.lastIndexOf(" CK"));
let x = 0; for (const ch of body) x ^= ch.charCodeAt(0);
const ck = x.toString(16).toUpperCase().padStart(2, "0");
if (ck !== m[11]) { node.status({fill:"red", shape:"dot", text:"bad checksum " + m[1]}); node.warn("bad checksum: " + raw); return null; }

const seen = context.get("seen") || {};
const nowMs = Date.now();
for (const k in seen) if (nowMs - seen[k] > DEDUP_SEC * 1000) delete seen[k];
if (seen[body]) { node.status({fill:"yellow", shape:"ring", text:"repeat " + m[1]}); return null; }
seen[body] = nowMs; context.set("seen", seen);

const call = m[1], type = m[2], text = m[9] || "", hhmm = m[10];
const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const iso = d => d.toISOString();
const now = new Date(), stale = new Date(nowMs + STALE_MIN * 60000);
const uid = "PagerRTTY-" + call;
const out = [];

let lat = null, lon = null;
if (m[3]) {
    lat = parseFloat(m[4]) * (m[5] === "S" ? -1 : 1);
    lon = parseFloat(m[6]) * (m[7] === "W" ? -1 : 1);
}
const pt = lat === null ? '<point lat="0" lon="0" hae="9999999" ce="9999999" le="9999999"/>'
                        : `<point lat="${lat}" lon="${lon}" hae="9999999" ce="25" le="9999999"/>`;

if (lat !== null) {
    out.push(`<event version="2.0" uid="${uid}" type="a-f-G-U-C" how="h-e" time="${iso(now)}" start="${iso(now)}" stale="${iso(stale)}">${pt}` +
      `<detail><contact callsign="${esc(call)}"/><__group name="Cyan" role="Team Member"/>` +
      `<remarks>PagerRTTY ${type} ${hhmm}Z via ${esc(rx)}${text ? " - " + esc(text) : ""}</remarks></detail></event>`);
}
if (type !== "LOC") {
    const id = uid + "-" + nowMs;
    const line = `[${type}] ${text}`.trim();
    out.push(`<event version="2.0" uid="GeoChat.${uid}.All Chat Rooms.${id}" type="b-t-f" how="h-g-i-g-o" time="${iso(now)}" start="${iso(now)}" stale="${iso(new Date(nowMs + 86400000))}">${pt}` +
      `<detail><__chat parent="RootContactGroup" groupOwner="false" messageId="${id}" chatroom="All Chat Rooms" id="All Chat Rooms" senderCallsign="${esc(call)}">` +
      `<chatgrp uid0="${uid}" uid1="All Chat Rooms" id="All Chat Rooms"/></__chat>` +
      `<link uid="${uid}" type="a-f-G-U-C" relation="p-p"/>` +
      `<remarks source="BAO.F.ATAK.${uid}" to="All Chat Rooms" time="${iso(now)}">${esc(line)}</remarks></detail></event>`);
}
node.status({fill:"green", shape:"dot", text:`${call} ${type} ${hhmm}Z`});
return [out.map(p => ({payload: p}))];
